// AVANT
function d(u) {
  let x = u * 86400;
  let y = Math.floor(x / 3600);
  return y + 'h';
}

function d2(u) {
  let x = u * 86400;
  let mins = Math.floor((x % 3600) / 60);
  return mins + 'min';
}

// APRÈS (refactorisé)
function convertirJoursEnSecondes(jours) {
  return jours * 86400;
}

function formaterHeures(jours) {
  const totalSecondes = convertirJoursEnSecondes(jours);
  const heures = Math.floor(totalSecondes / 3600);
  return heures + 'h';
}

function formaterMinutes(jours) {
  const totalSecondes = convertirJoursEnSecondes(jours);
  const minutes = Math.floor((totalSecondes % 3600) / 60);
  return minutes + 'min';
}
